    17: /// What allocation was asked for.
    18: #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    19: pub enum AddressRequest {
    20:     /// Take the lowest usable address not already reserved.
    21:     Automatic,
    22:     /// Take exactly this address, or explain why it cannot be used.
    23:     Requested(Ipv4Addr),
    24: }
    25: 
    26: /// Everything the allocator needs to know, gathered by the caller inside the
    27: /// mutation transaction.
    28: ///
    29: /// Note that `reserved_clients` deliberately includes *disabled* clients: a
    30: /// disabled client keeps its address, so its address must not be handed to
    31: /// somebody else and then collide when the first client is re-enabled.
    32: #[derive(Clone, Debug)]
    33: pub struct AllocationContext {
    34:     prefix: Ipv4Addr,
    35:     prefix_len: u8,
    36:     /// Server/interface addresses inside the prefix.
    37:     server_addresses: Vec<Ipv4Addr>,
    38:     /// Every managed client's address, enabled or not.
    39:     reserved_clients: Vec<Ipv4Addr>,
    40: }
