    42: impl AllocationContext {
    43:     /// Builds a context from the selected IPv4 tunnel prefix.
    44:     pub fn new(prefix: IpNet) -> Result<Self, AllocationError> {
    45:         let addr = prefix.addr();
    46:         if !addr.is_ipv4() {
    47:             return Err(AllocationError::NotIpv4);
    48:         }
    49:         let IpNet::V4(v4) = prefix else {
    50:             return Err(AllocationError::NotIpv4);
    51:         };
    52:         let (network, prefix_len) = (v4.network(), v4.prefix_len());
    53:         if prefix_len > 30 {
    54:             // A /31 has no usable host, and /32 is a single address rather than
    55:             // a pool. Treating either as a pool would hand out the network
    56:             // address or produce a range whose bounds cross.
    57:             return Err(AllocationError::PrefixTooSmall(prefix_len));
    58:         }
    59:         Ok(Self {
    60:             prefix: network,
    61:             prefix_len,
    62:             server_addresses: Vec::new(),
    63:             reserved_clients: Vec::new(),
    64:         })
    65:     }
