    93:         if size <= 2 {
    94:             // /31 or /32: no distinct network/broadcast pair exists to reserve.
    95:             return Ok((u32::from(self.prefix), last));
    96:         }
    97:         Ok((base as u32 + 1, last - 1))
    98:     }
